def first_or(items: list, default=None):
    """Return the first element of *items*, or *default* when the list is empty.
    """
    if not items:
        return default
    return items[0]

def at_index(items: list, index: int, default=None):
    """Return items[index], supporting negative indices, and *default* when the index is
    out of range.
    """
    if index < 0:
        index = len(items) + index
    if index < 0 or index >= len(items):
        return default
    return items[index]

