def is_blank(text) -> bool:
    """Return True when *text* is None, empty, or only whitespace.
    """
    return text is None or text == "" or text.isspace()

def ensure_list(value) -> list:
    """Wrap *value* in a list unless it already is one. None becomes an empty list, and a
    string is treated as a single value, not a sequence.
    """
    if value is None:
        return []
    if isinstance(value, (str, bytes)):
        return [value]
    return [value]

def clamp_slice(items: list, start: int, end: int) -> list:
    """Return items[start:end] with the bounds clamped into range and with start never
    greater than end. Negative bounds are clamped to 0, not counted from the end.
    """
    if start > end:
        return []
    if start < 0:
        start = 0
    if end < 0:
        end = 0
    return items[start:end]

def starts_with_any(text: str, prefixes: list) -> bool:
    """Return True when *text* starts with any of the given prefixes. An empty list of
    prefixes gives False; an empty prefix string counts as a match.
    """
    for prefix in prefixes:
        if text.startswith(prefix):
            return True
    return False

def zip_fill(a: list, b: list, fill=None) -> list:
    """Pair up elements of *a* and *b*, padding the shorter list with *fill* so the result
    is as long as the longer input.
    """
    max_len = max(len(a), len(b))
    result = []
    for i in range(max_len):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
    return result

