def deep_merge(a: dict, b: dict) -> dict:
    """Merge two nested dicts recursively and return a new dict. Where both sides hold a
    dict the merge continues one level deeper; otherwise the value from *b* wins.
    Neither input is modified.
    """
    result = {}
    all_keys = set(a.keys()) | set(b.keys())
    for key in all_keys:
        if key in a and key in b:
            if isinstance(a[key], dict) and isinstance(b[key], dict):
                result[key] = deep_merge(a[key], b[key])

def keys_with_value(mapping: dict, value) -> list:
    """Return the keys whose value equals *value*, sorted ascending.
    """
    return sorted([k for k, v in mapping.items() if v == value])

def invert_multi(mapping: dict) -> dict:
    """Invert a dict, collecting the keys that share a value into a sorted list.
    """
    inverted = {}
    for key, value in mapping.items():
        if value not in inverted:
            inverted[value] = []
        inverted[value].append(key)
    for value in sorted(inverted.keys()):
        inverted[value] = sorted(inverted[value])
    return inverted

