def deep_get_path(data, keys: list, default=None):
    """Walk a nested structure recursively following *keys*, returning *default* when a
    step is missing or the current value is not a dict. An empty key list returns the
    data itself.
    """
    if not keys:
        return data
    key = keys[0]
    if not isinstance(data, dict):
        return default
    if key not in data:
        return default
    return deep_get_path(data[key], keys[1:], default)

def count_down(n: int) -> list:
    """Return [n, n-1, ..., 1] using recursion. A non-positive n gives an empty list.
    """
    if n <= 0:
        return []
    return [n] + count_down(n - 1)

def is_subsequence(needle: str, haystack: str) -> bool:
    """Return True when every character of *needle* appears in *haystack* in the same
    order, not necessarily next to each other. An empty needle is always a
    subsequence.
    """
    i = 0
    for char in haystack:
        if i < len(needle) and char == needle[i]:
            i += 1
    return i == len(needle)

def lcs_length(a: str, b: str) -> int:
    """Return the length of the longest common subsequence of two strings.
    """
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

